\documentclass{article}
\usepackage[paperwidth=594mm,paperheight=841mm,margin=0mm]{geometry}
\usepackage{tcolorbox}
\tcbuselibrary{poster,skins,fitting}
\usepackage{graphicx}
\usepackage{amsmath,amssymb}
\usepackage{enumitem}
\usepackage[table]{xcolor}
\usepackage{lmodern}
\usepackage[T1]{fontenc}
\pagestyle{empty}

% ── UNICEF Color Theme ──
\definecolor{primary}{HTML}{0072BC}       % UNICEF Blue
\definecolor{secondary}{HTML}{E67E22}     % Warm Orange
\definecolor{accent}{HTML}{1CABE2}        % UNICEF Cyan
\definecolor{bgposter}{HTML}{EDF4FB}      % Light blue poster background
\definecolor{bluebg}{HTML}{DAEAF7}        % Light blue card tint
\definecolor{orangebg}{HTML}{FDE8D4}      % Light orange card tint
\definecolor{cyanbg}{HTML}{D4F1FA}        % Light cyan card tint
\definecolor{bluetitlebg}{HTML}{C8DFF2}   % Blue card title bg
\definecolor{orangetitlebg}{HTML}{FAD9BD}  % Orange card title bg
\definecolor{cyantitlebg}{HTML}{BDE8F7}   % Cyan card title bg
\definecolor{textdark}{HTML}{1F2937}      % Dark text
\definecolor{textgray}{HTML}{4B5563}      % Gray text
\definecolor{stathighlight}{HTML}{FFF3E6} % Warm stat highlight bg
\definecolor{herostatbg}{HTML}{FFF5EB}    % Hero stat warm bg
\definecolor{ctaaccent}{HTML}{F59E0B}     % Amber for CTA warmth

\pagecolor{bgposter}
\color{textdark}

% ── List styling ──
\setlist[itemize]{leftmargin=20pt, itemsep=8pt, parsep=2pt, topsep=2pt,
  label={\color{secondary}$\blacktriangleright$}}
\setlist[enumerate]{leftmargin=22pt, itemsep=6pt, parsep=2pt, topsep=2pt,
  label={\color{accent!80!black}\bfseries\arabic*.}}

% ── Card styles (left accent stripe design) ──
\tcbset{
  bluecard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=bluebg,
    borderline west={5pt}{0pt}{primary},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{34}{42}\selectfont\bfseries\color{primary},
    coltitle=primary, colbacktitle=bluetitlebg,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=2pt, titlerule style={primary!50},
    valign=top, drop shadow={opacity=0.18},
  },
  orangecard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=orangebg,
    borderline west={5pt}{0pt}{secondary},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{34}{42}\selectfont\bfseries\color{secondary!80!red},
    coltitle=secondary!80!red, colbacktitle=orangetitlebg,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=2pt, titlerule style={secondary!50},
    valign=top, drop shadow={opacity=0.18},
  },
  cyancard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=cyanbg,
    borderline west={5pt}{0pt}{accent},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{34}{42}\selectfont\bfseries\color{accent!70!black},
    coltitle=accent!70!black, colbacktitle=cyantitlebg,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=2pt, titlerule style={accent!50},
    valign=top, drop shadow={opacity=0.18},
  },
  highlightcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=primary!15!white,
    borderline west={6pt}{0pt}{primary},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{34}{42}\selectfont\bfseries\color{white},
    coltitle=white, colbacktitle=primary,
    toptitle=6pt, bottomtitle=6pt,
    valign=top, drop shadow={opacity=0.22},
  },
}

\begin{document}
\begin{tcbposter}[
  coverage={spread},
  poster={columns=2, rows=20, spacing=0mm},
]

% ══ TITLE BAR ══
\posterbox[
  enhanced, colback=primary, colframe=primary, colupper=white,
  arc=0pt, boxrule=0pt,
  left=30pt, right=30pt, top=12pt, bottom=10pt,
  halign=center, valign=center,
  drop shadow={opacity=0.3}
]{name=title, column=1, span=2, between=top and row3}{
  {\fontsize{68}{82}\selectfont\bfseries Every Child Deserves to Learn}\\[10pt]
  {\fontsize{28}{34}\selectfont UNICEF Global Education Campaign}\\[6pt]
  {\fontsize{18}{24}\selectfont\color{white!70} unicef.org/education}
}

% ══ HERO STAT: 250 MILLION ══
\posterbox[
  enhanced, colback=herostatbg, boxrule=0pt, arc=0pt,
  left=20pt, right=20pt, top=10pt, bottom=8pt,
  valign=center, halign=center,
  borderline south={4pt}{0pt}{secondary!50},
]{name=herostat, column=1, span=2, between=row3 and row6}{
  {\fontsize{74}{90}\selectfont\bfseries\color{secondary} 250 MILLION}\\[8pt]
  {\fontsize{26}{32}\selectfont\color{textdark} Children \& adolescents out of school worldwide}
}

% ══ SECONDARY STATS BANNER ══
\posterbox[
  enhanced, colback=primary!10!white, boxrule=0pt, arc=0pt,
  left=12pt, right=12pt, top=6pt, bottom=6pt,
  valign=center,
  borderline south={2pt}{0pt}{primary!30},
]{name=stats, column=1, span=2, between=row6 and row8}{
  \centering
  \begin{minipage}[c]{0.235\linewidth}\centering
    \fcolorbox{primary!40}{stathighlight}{\parbox{0.88\linewidth}{%
      \centering\vspace{5pt}%
      {\fontsize{44}{54}\selectfont\bfseries\color{primary} 70\%}\\[3pt]
      {\fontsize{18}{22}\selectfont\color{textdark} Cannot read by age 10}\vspace{5pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.235\linewidth}\centering
    \fcolorbox{primary!40}{stathighlight}{\parbox{0.88\linewidth}{%
      \centering\vspace{5pt}%
      {\fontsize{44}{54}\selectfont\bfseries\color{primary} 190+}\\[3pt]
      {\fontsize{18}{22}\selectfont\color{textdark} Countries with programmes}\vspace{5pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.235\linewidth}\centering
    \fcolorbox{secondary!40}{stathighlight}{\parbox{0.88\linewidth}{%
      \centering\vspace{5pt}%
      {\fontsize{44}{54}\selectfont\bfseries\color{secondary} 2.5$\times$}\\[3pt]
      {\fontsize{18}{22}\selectfont\color{textdark} Girls' exclusion in crises}\vspace{5pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.235\linewidth}\centering
    \fcolorbox{secondary!40}{stathighlight}{\parbox{0.88\linewidth}{%
      \centering\vspace{5pt}%
      {\fontsize{44}{54}\selectfont\bfseries\color{secondary} ${\sim}$49\%}\\[3pt]
      {\fontsize{18}{22}\selectfont\color{textdark} Disabilities out of school}\vspace{5pt}%
    }}
  \end{minipage}
}

% ══ CRISIS OVERVIEW (Left Column, Rows 8-14) ══
\posterbox[bluecard, title={The Global Education Crisis}
]{name=crisis, column=1, between=row8 and row14}{
  \fontsize{26}{34}\selectfont
  \begin{itemize}[itemsep=10pt]
    \item 250M children denied their right to education
    \item 70\% cannot read a simple text by age 10 --- ``learning poverty''
    \item Lost potential for individuals, communities, entire economies
  \end{itemize}
  \vspace{6pt}
  \colorbox{primary!20}{\parbox{0.92\linewidth}{%
    \centering\vspace{5pt}
    {\fontsize{22}{28}\selectfont\color{primary}\bfseries These figures represent not just lost potential for individual children, but enormous setbacks for communities and economies.}
    \vspace{5pt}
  }}
}

% ══ BARRIERS TO EDUCATION (Right Column, Rows 8-14) ══
\posterbox[orangecard, title={Barriers to Education}
]{name=barriers, column=2, between=row8 and row14}{
  \fontsize{26}{34}\selectfont
  \begin{itemize}[itemsep=8pt]
    \item \textbf{Conflict} --- schools destroyed, teachers displaced, children traumatized
    \item \textbf{Poverty} --- fees, supplies, child labour
    \item \textbf{Gender inequality} --- norms limit girls' access
    \item \textbf{Disability} --- ${\sim}$49\% never enter a classroom
    \item \textbf{Climate change} --- extreme weather disrupts schooling
  \end{itemize}
  \vspace{4pt}
  \colorbox{secondary!20}{\parbox{0.92\linewidth}{%
    \fontsize{20}{26}\selectfont\color{secondary!80!black}
    Girls are 2.5$\times$ more likely to be excluded from education in crisis-affected regions
    \vspace{2pt}
  }}
}

% ══ UNICEF FOCUS AREAS (Left Column, Rows 14-20) ══
\posterbox[cyancard, title={UNICEF's Education Focus}
]{name=focus, column=1, between=row14 and row20}{
  \fontsize{26}{34}\selectfont
  \begin{enumerate}[itemsep=6pt]
    \item Early childhood development
    \item Inclusive education for all
    \item Gender equality in education
    \item Education in emergencies
    \item Digital \& innovative learning
    \item Adolescent skills development
  \end{enumerate}
  \vspace{6pt}
  \colorbox{accent!20}{\parbox{0.92\linewidth}{%
    \fontsize{20}{26}\selectfont\color{accent!70!black}
    \textbf{Aligned with SDG 4:} Ensure inclusive and equitable quality education and promote lifelong learning opportunities for all
    \vspace{2pt}
  }}
}

% ══ CALL TO ACTION (Right Column, Rows 14-20) ══
\posterbox[highlightcard, title={What Can Be Done}
]{name=cta, column=2, between=row14 and row20}{
  \fontsize{26}{34}\selectfont\color{textdark}
  \begin{itemize}[itemsep=10pt]
    \item Education is a \textbf{fundamental child right}
    \item Investing in education $\Rightarrow$ investing in peace, innovation, sustainable development
    \item Governments, communities, organizations, and individuals must act together
  \end{itemize}
  \vspace{10pt}
  \colorbox{ctaaccent!30}{\parbox{0.92\linewidth}{%
    \centering\vspace{8pt}
    {\fontsize{28}{36}\selectfont\bfseries\color{secondary!85!red} Together, we can ensure\\that no child is left behind.}
    \vspace{8pt}
  }}
}

\end{tcbposter}
\end{document}

